 for(int i=0;i<6;i++){float x=i<3?-335:335,y=130-i%3*130;var field=SportsUIAuthoring.Name(p.transform,(i<3?"BLUE":"ORANGE")+" SLOT "+(i%3+1),m.players[i].name,new Vector2(x,y));field.GetComponent<RectTransform>().sizeDelta=new Vector2(550,48);p.transform.Find((i<3?"BLUE":"ORANGE")+" SLOT "+(i%3+1)).GetComponent<TMP_Text>().fontSizeMax=19;menu.names[i]=field;menu.sourceLabels[i]=SportsUIAuthoring.Button(p.transform,"SOURCE","source"+i,new Vector2(x-85,y-56),new Vector2(350,48)).normalTextObj;menu.levelLabels[i]=SportsUIAuthoring.Button(p.transform,"NORMAL","level"+i,new Vector2(x+200,y-56),new Vector2(170,48)).normalTextObj;}
 menu.name1=menu.names[0];menu.name2=menu.names[3];menu.difficultyText=menu.levelLabels[3];
 menu.color1Text=SportsUIAuthoring.Button(p.transform,"BLUE TEAM COLOR","color1",new Vector2(-440,-245),new Vector2(300,45)).normalTextObj;menu.color2Text=SportsUIAuthoring.Button(p.transform,"ORANGE TEAM COLOR","color2",new Vector2(-90,-245),new Vector2(330,45)).normalTextObj;menu.durationText=SportsUIAuthoring.Button(p.transform,"3 MINUTES","duration",new Vector2(360,-245),new Vector2(410,45)).normalTextObj;
