 for(int pageIndex=0;pageIndex<2;pageIndex++){int index=pageIndex==0?1:7;var join=SportsUIAuthoring.Page(pageIndex==0?"Join":"Disconnect",menu.transform,pageIndex==0?"JOIN CONTROLLERS":"CONTROLLER DISCONNECTED","A whole pad or individual sticks • Existing assignments are preserved");menu.pages[index]=join;var info=SportsUIAuthoring.Text("Device state",join.transform,"",new Vector2(1250,360),new Vector2(0,65),24);if(pageIndex==0)menu.joinInfo=info;else menu.disconnectInfo=info;for(int i=0;i<6;i++)SportsUIAuthoring.Button(join.transform,"REASSIGN "+(i<3?"B":"O")+(i%3+1),"reassign"+i,new Vector2((i%3-1)*395,-190-i/3*65),new Vector2(350,50));SportsUIAuthoring.Button(join.transform,pageIndex==0?"BACK":"SPORTS",pageIndex==0?"back":"front",new Vector2(-320,-370));SportsUIAuthoring.Button(join.transform,pageIndex==0?"START MATCH":"RESUME",pageIndex==0?"start":"resume",new Vector2(320,-370));}
