 public static void UpgradeFront(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);foreach(var t in UnityEngine.Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Include)){if(t.text.Contains("Continuous 1v1"))t.text="Continuous 3v3 on ice.\n0–6 humans; six AI can play a full match.\nKeyboard, whole pads or shared sticks.";if(t.name=="Guidance")t.text="BILLIARDS\nBumper strikes, stronger opening break, single racks or series. Human / AI slots, Practice and hot seat. Both groups potted legally? The shooter chooses.\n\nHOCKEY\n3v3 simultaneous driving. 0–6 humans with coordinated AI. Full puck crossing scores for the attacking TEAM; own goals count. Tied regulation enters sudden death. Rematches swap ends.\n\nHockey: opposite throttle brakes then reverses. Six editable keyboard clusters, whole controllers or left/right shared sticks. Start / Escape pauses; Pause recovers an individual slot.\n\nMenus: mouse, arrows / D-pad / stick; Enter / South submits. Input Check highlights all six sources. Test keyboard rollover on your hardware.";}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();if(System.IO.File.Exists(LWS.TruckBowling.Editor.BowlingAuthoring.Scene))LWS.TruckBowling.Editor.BowlingAuthoring.UpgradeFront();}
 public static void UpgradeAll(){UpgradeBilliards();UpgradeHockey();UpgradeFront();SportsBuilder.Validate();}
